// Generates `src/api/schema.gen.ts` from the backend's exported contract.
// The generated file is committed; never edit it by hand. Re-run after
// `backend/openapi.json` changes:  npm run gen:api
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

import openapiTS, { astToString } from "openapi-typescript";

const source = new URL("../../backend/openapi.json", import.meta.url);
const target = new URL("../src/api/schema.gen.ts", import.meta.url);

const document = JSON.parse(await readFile(source, "utf8"));
const ast = await openapiTS(document);
const header =
  "// GENERATED by `npm run gen:api` from backend/openapi.json. Do not edit.\n\n";
await writeFile(target, header + astToString(ast), "utf8");
console.log(`wrote ${fileURLToPath(target)}`);
